import{_ as o,C as l,o as e,c as r,j as i,E as d,a as s,a3 as n}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"8-sinf (Web Full-stack)","link":"/8-sinf/"},"n":2,"bob":"I-bob · HTML tili va veb-sahifa tuzishning asoslari","lessons":[{"g":4,"title":"Rasm va ro'yxat teglari: <img>, <figure>, <ul>, <ol>, <dl>","lead":"Surat mingta so'zdan afzal, ro'yxatlar esa har qanday chalkashlikni tartibga soladi. Ushbu darsda veb-sahifaga rasm joylash, to'g'ri manzillarni ko'rsatish va 3 xil ro'yxat turidan foydalanishni o'rganamiz.","link":"/8-sinf/hafta-02/dars-1","slide":"/slaydlar/8-sinf/hafta-02/dars-1.html","test":"/slaydlar/8-sinf/hafta-02/dars-1-test.html"},{"g":5,"title":"Jadval teglari: <table>, <tr>, <td>, <th>, colspan va rowspan","lead":"Dars jadvali, futbol chempionati turnir jadvali, internet-do'kondagi narxlar va xarid cheki — bularning barchasi jadvallardir. Ushbu darsda HTML yordamida qator va ustunlardan iborat chiroyli jadvallar yaratishni, katakchalarni birlashtirishni o'rganamiz.","link":"/8-sinf/hafta-02/dars-2","slide":"/slaydlar/8-sinf/hafta-02/dars-2.html","test":"/slaydlar/8-sinf/hafta-02/dars-2-test.html"},{"g":6,"title":"Forma elementlari va validatsiyasi: <form>, <input>, <label>, <select>, <textarea>","lead":"Veb-sayt shunchaki gazeta emas, u foydalanuvchi bilan muloqot qiladigan tirik tizimdir. Ushbu darsda saytlarga login qilish, xabar yuborish, so'rovnomalar to'ldirish va forma ma'lumotlarini to'g'ri tekshirishni (validatsiya) o'rganamiz.","link":"/8-sinf/hafta-02/dars-3","slide":"/slaydlar/8-sinf/hafta-02/dars-3.html","test":"/slaydlar/8-sinf/hafta-02/dars-3-test.html"}],"test":"/slaydlar/8-sinf/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"8-sinf/hafta-02/index.md","filePath":"8-sinf/hafta-02/index.md"}`),c={name:"8-sinf/hafta-02/index.md"},h={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function m(g,a,f,b,y,v){const t=l("Icon");return e(),r("div",null,[i("div",h,[i("h2",u,[d(t,{name:"house"}),a[0]||(a[0]=s(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=n('<p>Har bir vazifa 20–30 daqiqa. Fayllar alohida <code>hafta-02</code> papkasida saqlanadi.</p><h3 id="_4-dars-uchun-rasm-va-ro-yxat-teglari" tabindex="-1">4-dars uchun (Rasm va ro&#39;yxat teglari) <a class="header-anchor" href="#_4-dars-uchun-rasm-va-ro-yxat-teglari" aria-label="Permalink to &quot;4-dars uchun (Rasm va ro&#39;yxat teglari)&quot;">​</a></h3><p><strong>1-topshiriq: «Mening sevimli mavzum» sahifasi</strong></p><ul><li>O&#39;zingiz qiziqqan mavzuda (sport, o&#39;yin, kitob yoki tabiat) <code>qiziqish.html</code> sahifasini tayyorlang.</li><li>Sahifada kamida 2 ta rasm (<code>&lt;img&gt;</code>, to&#39;g&#39;ri <code>alt</code>, <code>width</code> va <code>height</code> bilan) bo&#39;lsin.</li><li>Bitta rasm <code>&lt;figure&gt;</code> va <code>&lt;figcaption&gt;</code> bilan o&#39;ralsin.</li><li>Mavzuga oid 1 ta tartiblangan (<code>&lt;ol&gt;</code>), 1 ta tartibsiz (<code>&lt;ul&gt;</code>) va 1 ta ta&#39;riflar ro&#39;yxati (<code>&lt;dl&gt;</code>) yarating.</li><li><strong>Tekshirish:</strong> barcha rasmlar to&#39;g&#39;ri yuklanadi, <code>alt</code> mavjud, ro&#39;yxatlar ichma-ich sintaktik xatosiz yozilgan.</li></ul><h3 id="_5-dars-uchun-jadval-teglari-colspan-rowspan" tabindex="-1">5-dars uchun (Jadval teglari, colspan, rowspan) <a class="header-anchor" href="#_5-dars-uchun-jadval-teglari-colspan-rowspan" aria-label="Permalink to &quot;5-dars uchun (Jadval teglari, colspan, rowspan)&quot;">​</a></h3><p><strong>2-topshiriq: «Oylik reja va xarajatlar» jadvali</strong></p><ul><li><code>jadval.html</code> faylini yarating.</li><li>Unda <code>&lt;caption&gt;</code>, <code>&lt;thead&gt;</code>, <code>&lt;tbody&gt;</code> va <code>&lt;tfoot&gt;</code> semantik bo&#39;limlari bo&#39;lsin.</li><li>Kamida 4 ta ustun: №, Xarajat moddasi, Miqdori, Narxi.</li><li>Eng pastki <code>&lt;tfoot&gt;</code> qatorida <code>colspan</code> yordamida &quot;Jami xarajat&quot; hisoblansin.</li><li>Ixtiyoriy: biror qatorda <code>rowspan</code> qo&#39;llab ko&#39;ring (masalan, bir xil toifadagi xarajatlar uchun).</li><li><strong>Tekshirish:</strong> jadval ramkasi buzilmagan, katakchalar matematik muvozanatda, brauzerda to&#39;g&#39;ri tekislangan.</li></ul><h3 id="_6-dars-uchun-forma-elementlari-va-validatsiya" tabindex="-1">6-dars uchun (Forma elementlari va validatsiya) <a class="header-anchor" href="#_6-dars-uchun-forma-elementlari-va-validatsiya" aria-label="Permalink to &quot;6-dars uchun (Forma elementlari va validatsiya)&quot;">​</a></h3><p><strong>3-topshiriq: «Klubga a&#39;zo bo&#39;lish» formasi</strong></p><ul><li><code>forma.html</code> faylini yarating.</li><li><code>&lt;form action=&quot;#&quot; method=&quot;POST&quot;&gt;</code> oching.</li><li>Unda quyidagi maydonlar bo&#39;lsin va har biri o&#39;z <code>&lt;label&gt;</code>iga (<code>for</code> va <code>id</code>) ega bo&#39;lsin: <ol><li>Ism va familiya (<code>type=&quot;text&quot;</code>, <code>required</code>);</li><li>Email (<code>type=&quot;email&quot;</code>, <code>placeholder</code>);</li><li>Parol (<code>type=&quot;password&quot;</code>, <code>required</code>);</li><li>Qiziqishlar (<code>type=&quot;checkbox&quot;</code>, kamida 3 ta variant);</li><li>Dars vaqti (<code>type=&quot;radio&quot;</code>, bir xil <code>name</code> bilan 2 ta variant);</li><li>Viloyat (<code>&lt;select&gt;</code> va <code>&lt;option&gt;</code>);</li><li>O&#39;zingiz haqingizda qo&#39;shimcha ma&#39;lumot (<code>&lt;textarea&gt;</code>);</li><li>&quot;A&#39;zo bo&#39;lish&quot; tugmasi (<code>&lt;button type=&quot;submit&quot;&gt;</code>).</li></ol></li><li><strong>Tekshirish:</strong> bo&#39;sh holatda yuborishga urinilganda brauzer ogohlantirish beradi, radio tugmalardan faqat bittasi tanlanadi, label bosilganda kursor maydonga tushadi.</li></ul>',10))])])}const k=o(c,[["render",m]]);export{p as __pageData,k as default};
